import com.koios.game.model.*;import com.koios.game.model.mob.Mob;import com.koios.game.model.player.update.MobUpdater;import com.koios.network.*;
public final class NpcHealthPacketCheck {
 static int checks;static void check(boolean b,String msg){checks++;if(!b)throw new AssertionError(msg);}
 static int[] health(byte[] b,int offset,boolean second){return new int[]{second?(b[offset]-128)&255:(128-b[offset])&255,second?b[offset+1]&255:(-b[offset+1])&255};}
 static void pair(int[] got,int hp,int max,String msg){check(got[0]==hp&&got[1]==max,msg+": got"+got[0]+"/"+got[1]);}
 public static void main(String[]args)throws Exception{PrototypeIntegrationCheck.loaded();MobUpdater updater=new MobUpdater();
 for(int maximum:new int[]{0,100,255,256,470,Integer.MAX_VALUE})for(int current:new int[]{-1,0,1,255,256,470,Integer.MAX_VALUE})for(int mode=0;mode<3;mode++){
 Mob mob=new Mob(73,new Location(3094,3493,0)){};mob.maximumHitpoints=maximum;mob.hitpoints=Math.max(1,maximum);mob.setDamage(new Damage(0),null);mob.setDamage(new Damage(0),null);mob.hitpoints=current;for(UpdateFlags.UpdateFlag flag:UpdateFlags.UpdateFlag.values())mob.getUpdateFlags().set(flag,false);if(mode!=1)mob.getUpdateFlags().flag(UpdateFlags.UpdateFlag.HIT);if(mode!=0)mob.getUpdateFlags().flag(UpdateFlags.UpdateFlag.HIT_2);GamePacketBuilder buffer=new GamePacketBuilder();updater.appendNPCUpdateBlock(mob,buffer,false);GamePacket packet=buffer.toPacket();byte[] bytes=new byte[packet.getSize()];packet.getBuffer().getBytes(packet.getBuffer().readerIndex(),bytes);int bounded=Math.max(0,Math.min(maximum,current)),expectedMax=maximum>255?100:maximum,expectedHp=maximum>255?(bounded==0?0:Math.max(1,(int)((long)bounded*100/maximum))):bounded;
 check(bytes.length==(mode==2?15:8),"No hit block wire-length changes");if(mode!=0)pair(health(bytes,6,true),expectedHp,expectedMax,"Secondary hit consistent bounded health");if(mode!=1)pair(health(bytes,mode==2?13:6,false),expectedHp,expectedMax,"Primary hit consistent bounded health");check(expectedHp>=0&&expectedHp<=expectedMax&&(bounded==0?expectedHp==0:expectedHp>0),"Positive live bar, zero dead bar, bounded scale");if(maximum<=255&&current>=0&&current<=maximum)check(expectedHp==current&&expectedMax==maximum,"Legacy byte-sized max health unchanged");}
 System.out.println("Passed "+checks+" NPC health packet checks across both hit blocks.");}
}
